      unit: "Качан 350-450 г",
      inStock: true,
    });
  });

  test("Unknown id", async () => {
    const res = await app.request("/api/products/osio:000000000000000000000000");

    expect(res.status).toBe(404);
    expect(await res.json()).toEqual({ error: "Product not found" });
  });
});

