  const payload = rawBody ?? (body === undefined ? undefined : JSON.stringify(body));
  return app.request(path, {
    method,
    headers: {
      ...(cookie === undefined ? {} : { Cookie: cookie }),
      ...(payload === undefined ? {} : { "Content-Type": "application/json" }),
    },
    body: payload,
